import { createBrowserRouter } from 'react-router-dom';
import React from 'react';

// Layouts
import { PublicLayout } from '../components/layout/PublicLayout';
import { AdminLayout } from '../components/layout/AdminLayout';

// Public Pages
import { Home } from '../pages/public/Home';
import { FormPengajuan } from '../pages/public/FormPengajuan';
import { TrackStatus } from '../pages/public/TrackStatus';
import { ValidasiSurat } from '../pages/public/ValidasiSurat';
import { ValidasiKades } from '../pages/public/ValidasiKades';

// Admin Pages
import { Login } from '../pages/auth/Login';
import { SessionExpired } from '../pages/auth/SessionExpired';
import { Dashboard } from '../pages/admin/Dashboard';
import { AntreanSurat } from '../pages/admin/AntreanSurat';
import { DetailPengajuan } from '../pages/admin/DetailPengajuan';
import { PengaturanWA } from '../pages/admin/PengaturanWA';
import { Laporan } from '../pages/admin/Laporan';
import { DataWarga } from '../pages/admin/DataWarga';
import { PengaturanAkun } from '../pages/admin/PengaturanAkun';
import { ContohSurat } from '../pages/admin/ContohSurat';

// Mock Pages (Temporary placeholders removed)

export const router = createBrowserRouter([
  {
    path: '/',
    element: <PublicLayout />,
    children: [
      {
        index: true,
        element: <Home />
      },
      {
        path: 'ajukan',
        element: <FormPengajuan />
      },
      {
        path: 'track',
        element: <TrackStatus />
      },
      {
        path: 'validasi/:token',
        element: <ValidasiSurat />
      },
      {
        path: 'validasi-kades/:token',
        element: <ValidasiKades />
      }
    ]
  },
  {
    path: '/login',
    element: <Login />
  },
  {
    path: '/session-expired',
    element: <SessionExpired />
  },
  {
    path: '/admin',
    element: <AdminLayout />,
    children: [
      {
        index: true,
        element: <Dashboard />
      },
      {
        path: 'pengajuan',
        element: <AntreanSurat />
      },
      {
        path: 'pengajuan/:id',
        element: <DetailPengajuan />
      },
      {
        path: 'pengaturan-wa',
        element: <PengaturanWA />
      },
      {
        path: 'laporan',
        element: <Laporan />
      },
      {
        path: 'warga',
        element: <DataWarga />
      },
      {
        path: 'pengaturan-akun',
        element: <PengaturanAkun />
      },
      {
        path: 'contoh-surat',
        element: <ContohSurat />
      }
    ]
  }
]);
